// Reads the web schema from `cookbook-cli schema web` on stdin and writes src/lib/types/recipe.ts.
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { compile } from 'json-schema-to-typescript';

const chunks = [];
for await (const chunk of process.stdin) chunks.push(chunk);
const schema = JSON.parse(Buffer.concat(chunks).toString('utf8'));

const banner =
	'/* Generated by `pnpm gen:types` from `cookbook-cli schema web`. Do not edit by hand. */';
const raw = await compile(schema, 'Web', {
	bannerComment: banner,
	unreachableDefinitions: true,
	additionalProperties: false,
	format: true,
	style: { useTabs: true, singleQuote: true, printWidth: 100, trailingComma: 'none' }
});

const output = raw
	.replace(
		/\/\*\*\n \* This interface was referenced by `Web`'s JSON-Schema\n \* via the `definition` "\w+"\.\n \*\/\n/g,
		''
	)
	.replace(/export interface Web \{\n\s*\[k: string\]: unknown;?\n\}\n/, '');

const target = resolve(import.meta.dirname, '../src/lib/types/recipe.ts');
mkdirSync(dirname(target), { recursive: true });
writeFileSync(target, output);
